program.draw:
paint.rect(0,0,width,height,'#0b1729');
const margin=32;
const circuitW=width*0.4;
const plotW=width-circuitW-2*margin;
const plotX=circuitW+margin;
const plotY=margin;
const plotH=height-2*margin;
const cx=circuitW/2;
const cy=height/2;
const nodeRadius=6;
const batteryLen=40;
const resistorLen=60;
const capacitorGap=30;
const x0=margin;
const y0=cy;
const x1=x0+batteryLen;
const x2=x1+resistorLen;
const x3=x2+capacitorGap;
const x4=x3+30;
// battery
paint.line(x0-10,y0-15,x0-10,y0+15,'#fff',2);
paint.line(x0+10,y0-15,x0+10,y0+15,'#fff',2);
paint.line(x0-10,y0,x0+10,y0,'#fff',2);
paint.text(x0-12,y0-20,`${state.Vb}V`,'#fff',12);
// resistor (simple line)
paint.line(x1,y0,x2,y0,'#fff',2);
// capacitor
paint.line(x2,y0-20,x2,y0+20,'#fff',2);
paint.line(x3,y0-20,x3,y0+20,'#fff',2);
paint.line(x3,y0,x4,y0,'#fff',2);
// nodes
paint.circle(x0,y0,nodeRadius,'#fff');
paint.circle(x4,y0,nodeRadius,'#fff');
// capacitor voltage label
paint.text(x3+5,y0-25,`Vc=${state.Vc.toFixed(2)}V`,'#fff',12);
// plot axes
paint.line(plotX,plotY+plotH,plotX+plotW,plotY+plotH,'#fff',2);
paint.line(plotX,plotY,plotX,plotY+plotH,'#fff',2);
paint.text(plotX,plotY+plotH+15,'t (s)','#fff',12);
paint.text(plotX-20,plotY,`V (${state.Vb}V)`,'#fff',12);
// plot curve
const maxT=10; // presentation time span
const scaleX=plotW/maxT;
const scaleY=plotH/state.Vb;
for(let i=1;i<state.history.length;i++){
  const p0=state.history[i-1];
  const p1=state.history[i];
  const x0=plotX+p0.t*scaleX;
  const y0=plotY+plotH-p0.Vc*scaleY;
  const x1=plotX+p1.t*scaleX;
  const y1=plotY+plotH-p1.Vc*scaleY;
  paint.line(x0,y0,x1,y1,'#0f0',2);
}
if(state.history.length){
  const last=state.history[state.history.length-1];
  const mx=plotX+last.t*scaleX;
  const my=plotY+plotH-last.Vc*scaleY;
  paint.circle(mx,my,4,'#f00');
}
